def solve(n):
    if n <= 2:
        return 0
    # sieve over odd numbers < n; index i represents 2*i + 1
    half = n // 2
    sieve = bytearray([1]) * half
    sieve[0] = 0  # 1 is not prime
    i = 1
    while True:
        p = 2 * i + 1
        if p * p >= n:
            break
        if sieve[i]:
            start = (p * p) // 2
            step = p
            cnt = len(range(start, half, step))
            sieve[start:half:step] = bytearray(cnt)
        i += 1
    return sum(sieve) + 1  # +1 counts the prime 2 (n > 2 here)

