def solve(words, k):
    """Return the k most frequent words, breaking ties alphabetically.
    If k <= 0, return an empty list. If k exceeds the number of distinct words,
    return all words sorted by the required criteria.
    """
    # Defensive checks
    if not isinstance(k, int) or k <= 0:
        return []
    # Count frequencies
    freq = {}
    for w in words:
        # Ensure hashable; skip unhashable types
        try:
            freq[w] = freq.get(w, 0) + 1
        except Exception:
            continue
    # Create list of (word, count)
    items = list(freq.items())
    # Sort by descending frequency then ascending word (alphabetical)
    items.sort(key=lambda x: (-x[1], x[0]))
    # Take first k words
    return [word for word, _ in items[:k]]
}

